        }
    }
    #pragma unroll
    for(int k=0;k<10;k++) sh[k][t]=v[k];
    __syncthreads();
    for(int off=blockDim.x/2;off;off>>=1) {
        if(t<off) {
            #pragma unroll
            for(int k=0;k<10;k++) sh[k][t]+=sh[k][t+off];
        }
        __syncthreads();
