    if(!t) {
        #pragma unroll
        for(int k=0;k<9;k++) atomicAdd(H+k,sh[k][0]);
        atomicAdd(err,sh[9][0]);
    }
}

__global__ void finish(const double* H, const double* e, float* ho, float* eo) {
    int t=threadIdx.x;
    if(t<9) ho[t]=(float)H[t];
    if(t==9) *eo=(float)*e;
}

static void scratch(int N) {
    if (N > g_match_cap) {
        if (g_match) cudaFree(g_match);
        cudaMalloc(&g_match, (size_t)N*sizeof(int));
        g_match_cap=N;
    }
    if (!g_sums) cudaMalloc(&g_sums,6*sizeof(double));
    if (!g_hsum) cudaMalloc(&g_hsum,9*sizeof(double));
    if (!g_esum) cudaMalloc(&g_esum,sizeof(double));
}

void icp_correspondence(const float* src, const float* tgt, int N, int M,
                        float d_max, const void* kd_nodes, int n_nodes,
                        float* H_out, float* err_out, int* count_out,
                        cudaStream_t stream) {
    (void)M; (void)n_nodes;
    scratch(N);
    cudaMemsetAsync(g_sums,0,6*sizeof(double),stream);
    cudaMemsetAsync(g_hsum,0,9*sizeof(double),stream);
    cudaMemsetAsync(g_esum,0,sizeof(double),stream);
    cudaMemsetAsync(count_out,0,sizeof(int),stream);
    constexpr int block=256;
    int grid=(N+block-1)/block;
    find_matches<<<grid,block,0,stream>>>(src,tgt,(const KDNode*)kd_nodes,N,
                                           d_max*d_max,g_match,g_sums,count_out);
    make_centroid<<<1,1,0,stream>>>(g_sums,count_out);
    accumulate<<<grid,block,0,stream>>>(src,tgt,g_match,N,g_sums,g_hsum,g_esum);
    finish<<<1,32,0,stream>>>(g_hsum,g_esum,H_out,err_out);
}
